```ts
import { DurableObject } from "cloudflare:workers";

const WAKE_INTERVAL_MS = 60 * 60 * 1000;

export interface Env {}

export class ChatRoom extends DurableObject<Env> {
  // Tail of the write chain. Each write waits for the previous one to settle.
  private writeChain: Promise<unknown> = Promise.resolve();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          created_at INTEGER NOT NULL
        )
      `);
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + WAKE_INTERVAL_MS);
      }
    });
  }

  // Runs fn after every earlier write has settled, so writes that span awaits never interleave.
  private serialize<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.writeChain.then(() => fn());
    this.writeChain = run.catch(() => {});
    return run;
  }

  async postMessage(author: string, body: string): Promise<number> {
    return this.serialize(async () => {
      const row = this.ctx.storage.sql
        .exec<{ id: number }>(
          "INSERT INTO messages (author, body, created_at) VALUES (?, ?, ?) RETURNING id",
          author,
          body,
          Date.now(),
        )
        .one();
      return row.id;
    });
  }

  async alarm(): Promise<void> {
    // Reschedule first so the hourly cadence holds even if the work below throws.
    await this.ctx.storage.setAlarm(Date.now() + WAKE_INTERVAL_MS);
    await this.serialize(async () => {
      await this.onWake();
    });
  }

  // Hourly work goes here. Placeholder: drop messages older than 30 days.
  private async onWake(): Promise<void> {
    const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
    this.ctx.storage.sql.exec("DELETE FROM messages WHERE created_at < ?", cutoff);
  }
}
```

The class serializes writes through a promise chain, so a write that awaits external I/O cannot interleave with another. The alarm re-arms itself every hour, and the constructor arms it on first load if none is set. The wrangler config needs a `new_sqlite_classes` migration for `ChatRoom`, and I have not run or deployed this.
